"""Process-local signature policies for registered image mirrors.

Each mirror keeps at most one signature policy naming the HMAC algorithm,
the trusted key identifiers and whether the signature must cover the layer
digest. Policies live only in process memory: a restart clears every
record, and pull-time verification is always recomputed from the request
headers against the stored policy.
"""

from __future__ import annotations

from dataclasses import dataclass

#: The two supported HMAC algorithms; matching is case-sensitive.
ALGORITHMS: tuple[str, ...] = ("hmac-sha256", "hmac-sha512")

#: Fields accepted by the registration request; anything else is rejected.
_ALLOWED_FIELDS = frozenset({"algorithm", "keys", "cover_digest"})
_REQUIRED_FIELDS = ("algorithm", "keys", "cover_digest")


class MirrorPolicyValidationError(ValueError):
    """A signature policy payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class MirrorPolicyError(ValueError):
    """A signature policy operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class MirrorPolicy:
    """The single signature policy stored for a mirror."""

    algorithm: str
    keys: tuple[str, ...]
    cover_digest: bool

    def to_dict(self, mirror_id: str) -> dict[str, object]:
        return {
            "id": mirror_id,
            "algorithm": self.algorithm,
            "keys": list(self.keys),
            "cover_digest": self.cover_digest,
        }


def build_mirror_policy_fields(
    payload: object,
) -> tuple[str, tuple[str, ...], bool]:
    """Validate a decoded policy payload and return normalized values.

    Returns ``(algorithm, keys, cover_digest)``. The key list keeps its
    submitted order and is stored verbatim; it must be a non-empty array
    of distinct non-empty strings.
    """

    if not isinstance(payload, dict):
        raise MirrorPolicyValidationError(
            "Request body must be a JSON object."
        )

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise MirrorPolicyValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise MirrorPolicyValidationError(
                f"Missing required field: {field!r}."
            )

    algorithm = payload["algorithm"]
    if not isinstance(algorithm, str) or algorithm not in ALGORITHMS:
        allowed = ", ".join(ALGORITHMS)
        raise MirrorPolicyValidationError(
            f"Field 'algorithm' must be one of: {allowed} (case-sensitive)."
        )

    raw_keys = payload["keys"]
    if not isinstance(raw_keys, list):
        raise MirrorPolicyValidationError("Field 'keys' must be an array.")
    if not raw_keys:
        raise MirrorPolicyValidationError("Field 'keys' must not be empty.")
    keys: list[str] = []
    for element in raw_keys:
        if not isinstance(element, str):
            raise MirrorPolicyValidationError(
                "Field 'keys' elements must be strings."
            )
        if not element:
            raise MirrorPolicyValidationError(
                "Field 'keys' elements must not be empty."
            )
        if element in keys:
            raise MirrorPolicyValidationError(
                "Field 'keys' elements must not repeat."
            )
        keys.append(element)

    cover_digest = payload["cover_digest"]
    if not isinstance(cover_digest, bool):
        raise MirrorPolicyValidationError(
            "Field 'cover_digest' must be a boolean."
        )

    return algorithm, tuple(keys), cover_digest


class MirrorPolicyStore:
    """Process-local storage of at most one signature policy per mirror."""

    def __init__(self) -> None:
        self._policies: dict[str, MirrorPolicy] = {}

    def reset(self) -> None:
        self._policies = {}

    def get(self, mirror_id: str) -> MirrorPolicy | None:
        return self._policies.get(mirror_id)

    def remove(self, mirror_id: str) -> MirrorPolicy | None:
        """Remove and return the policy for ``mirror_id``, else ``None``.

        A missing or already removed policy changes nothing.
        """

        return self._policies.pop(mirror_id, None)

    def add(
        self, mirror_id: str, payload: object
    ) -> tuple[MirrorPolicy, bool]:
        """Validate and record the signature policy for ``mirror_id``.

        Returns ``(policy, created)`` where ``created`` is ``True`` for a
        first registration (HTTP 201) and ``False`` for an idempotent
        repeat of the exact same content (HTTP 200).

        Raises :class:`MirrorPolicyValidationError` for an invalid payload
        or :class:`MirrorPolicyError` with code ``mirror_policy_conflict``
        when a different policy is already stored; the stored policy is
        never overwritten.
        """

        algorithm, keys, cover_digest = build_mirror_policy_fields(payload)
        policy = MirrorPolicy(
            algorithm=algorithm, keys=keys, cover_digest=cover_digest
        )

        existing = self._policies.get(mirror_id)
        if existing is not None:
            if existing == policy:
                return existing, False
            raise MirrorPolicyError(
                "mirror_policy_conflict",
                "A different signature policy is already registered for "
                "this mirror.",
            )

        self._policies[mirror_id] = policy
        return policy, True

        allowed="GET, POST",
    )


def _handle_signature_verify(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "POST":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="POST",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    # Read-only: verification takes no request body and derives every input
    # from the stored record, so it never reads the request stream.
    resource = store.get(raw_id)
    if resource is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    registered = signature_store.get(raw_id)
    if registered is None:
        return _error(
            start_response,
            "404 Not Found",
            "signature_not_found",
            "No content signature is registered for this resource.",
        )

    # The signed digest must be the resource's registered digest.
    if registered.digest != resource.digest:
        return _error(
            start_response,
            "409 Conflict",
            "signed_digest_mismatch",
            "The signature digest does not match the resource digest.",
        )

    # Recompute the HMAC from the stored fields and compare it with the
    # registered signature value; nothing about this check is recorded.
    expected = compute_signature(
        registered.algorithm, registered.key_id, registered.digest
    )
    valid = hmac.compare_digest(expected, registered.signature)
    return _json_response(
        start_response,
        "200 OK",
        {"id": raw_id, "valid": valid},
        trailing_newline=True,
    )


def application(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    try:
        method = str(environ.get("REQUEST_METHOD", "GET")).upper()
        path = str(environ.get("PATH_INFO", "/"))

        if method == "GET" and path == "/health":
            # Kept byte-for-byte compatible with the documented baseline.
            return _json_response(start_response, "200 OK", {"status": "ok"})

        if path == "/resources":
            if method == "GET":
                return _handle_resources_get(environ, start_response)
            if method == "POST":
                return _handle_resources_post(environ, start_response)
            return _error(
                start_response,
                "405 Method Not Allowed",
                "method_not_allowed",
                f"Method {method} is not allowed for this path.",
                allowed="GET, POST",
            )

        if path == "/cache":
            return _handle_cache_root(method, environ, start_response)

        if path == "/cache/status":
            return _handle_cache_status(method, environ, start_response)

        if path.startswith("/cache/layers/"):
            return _handle_cache_layer(
                method, environ, path[len("/cache/layers/"):], start_response
            )

        if path == "/mirrors":
            return _handle_mirrors(method, environ, start_response)

        if path.startswith("/mirrors/"):
            suffix = path[len("/mirrors/"):]
            marker = "/pull/"
            marker_index = suffix.find(marker)
            if marker_index >= 0:
                # Split on the pull marker even when the id segment embeds a
                # separator, so the pull handler can reject the id as a bad
                # request instead of treating the path as an unknown item.
                return _handle_mirror_pull(
                    method,
                    environ,
                    suffix[:marker_index],
                    suffix[marker_index + len(marker):],
                    start_response,
                )
            if suffix.endswith("/pull"):
                # A pull always names a digest; an empty segment is invalid.
                return _handle_mirror_pull(
                    method,
                    environ,
                    suffix[: -len("/pull")],
                    "",
                    start_response,
                )
            if suffix.endswith("/signature-policy"):
                # Split on the policy marker even when the id segment embeds
                # a separator, so the handler can reject the id as a bad
                # request instead of treating the path as an unknown item.
                return _handle_mirror_signature_policy(
                    method,
                    environ,
                    suffix[: -len("/signature-policy")],
                    start_response,
                )
            head, separator, _tail = suffix.partition("/")
            if not separator:
                return _handle_mirror_item(
                    method, environ, head, start_response
                )
            # Any other suffix embeds a separator in the id segment; the
            # item handler rejects it without touching any state.
            return _handle_mirror_item(
                method, environ, suffix, start_response
            )

        if path.startswith("/resources/"):
            suffix = path[len("/resources/"):]
            head, separator, tail = suffix.partition("/")
            if separator and tail == "dependencies":
                return _handle_dependencies(
                    method, environ, head, start_response
                )
            if separator and tail == "impact":
                return _handle_impact(
                    method, environ, head, start_response
                )
            if separator and tail == "dependency-vulnerability-impact":
                return _handle_dependency_vulnerability_impact(
                    method, environ, head, start_response
                )
            if separator and tail == "verify":
                return _handle_verify(
                    method, environ, head, start_response
                )
            if separator and tail == "assemble":
                return _handle_assemble(
                    method, environ, head, start_response
                )
            if separator and tail == "content":
                return _handle_content(
                    method, environ, head, start_response
                )
            if separator and tail == "lifecycle":
                return _handle_lifecycle(
                    method, environ, head, start_response
                )
            if separator and tail == "release-blockers":
                return _handle_release_blockers(
                    method, environ, head, start_response
                )
            if separator and tail == "vulnerabilities":
                return _handle_vulnerabilities(
                    method, environ, head, start_response
                )
            if separator and tail == "vulnerability-exceptions":
                return _handle_vulnerability_exceptions(
                    method, environ, head, start_response
                )
            if separator and tail.startswith("vulnerability-exceptions/"):
                return _handle_vulnerability_exception_item(
                    method,
                    environ,
                    head,
                    tail[len("vulnerability-exceptions/"):],
                    start_response,
                )
            if separator and tail == "sbom":
                return _handle_sbom(
                    method, environ, head, start_response
                )
            if separator and tail == "license":
                return _handle_license(
                    method, environ, head, start_response
                )
            if separator and tail == "provenance":
                return _handle_provenance(
                    method, environ, head, start_response
                )
            if separator and tail == "policies":
                return _handle_policies(
                    method, environ, head, start_response
                )
            if separator and tail == "admission":
                return _handle_admission(
                    method, environ, head, start_response
                )
            if separator and tail == "admission-preview":
                return _handle_admission_preview(
                    method, environ, head, start_response
                )
            if separator and tail == "risk":
                return _handle_risk(
                    method, environ, head, start_response
                )
            if separator and tail == "component-risks":
                return _handle_component_risks(
                    method, environ, head, start_response
                )
            if separator and tail == "component-fixes":
                return _handle_component_fixes(
                    method, environ, head, start_response
                )
            if separator and tail == "notifications":
                return _handle_notifications(
